<script setup lang="ts">import {usePropertyStore} from '@/hooks/property';import {tripleRingDefaults} from '@/triple-ring';const property=usePropertyStore();</script><template><section><h3>三层时间圆环</h3><p>外圈秒 · 中圈分钟 · 内圈小时</p><label>主题<select :value="property.settings.theme||'orange'" @change="property.settings.theme=($event.target as HTMLSelectElement).value"><option value="orange">曜石橙</option><option value="ice">冰川蓝</option><option value="violet">星云紫</option></select></label><label>圆环平滑推进<input type="checkbox" :checked="property.settings.smooth!==false" @change="property.settings.smooth=($event.target as HTMLInputElement).checked"></label><label>显示秒钟<input type="checkbox" :checked="property.settings.showSeconds!==false" @change="property.settings.showSeconds=($event.target as HTMLInputElement).checked"></label><label>显示日期<input type="checkbox" :checked="property.settings.showDate!==false" @change="property.settings.showDate=($event.target as HTMLInputElement).checked"></label><label>显示圆环标签<input type="checkbox" :checked="property.settings.labels!==false" @change="property.settings.labels=($event.target as HTMLInputElement).checked"></label><label>发光强度<input type="range" min="20" max="100" step="5" :value="property.settings.glow||85" @input="property.settings.glow=Number(($event.target as HTMLInputElement).value)"></label><label>图像传输<select :value="property.settings.transport||'compatible'" @change="property.settings.transport=($event.target as HTMLSelectElement).value"><option value="compatible">兼容模式</option><option value="binary">二进制 PNG（实验）</option></select></label><button @click="Object.assign(property.settings,tripleRingDefaults)">恢复默认</button></section></template><style scoped>section{padding:16px;color:#eee;font:13px 'Microsoft YaHei',sans-serif}label{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:16px 0}p{opacity:.65;line-height:1.7}button,select{padding:7px;background:#25292e;color:#fff;border:1px solid #626a72;border-radius:5px}button{cursor:pointer}input[type=range]{width:120px}</style>
